import sys; sys.path.insert(0,'/workspace')
import jax, jax.numpy as jnp, importlib.util
spec=importlib.util.spec_from_file_location("lo","/tmp/losses_orig.py"); lo=importlib.util.module_from_spec(spec); spec.loader.exec_module(lo)
import losses
V,K,D=50,5,8
W=jax.random.normal(jax.random.key(0),(D,V)); h=jax.random.normal(jax.random.key(1),(1,2,D))
p_logits=h[0,0]@W
def exp_grad(mod,qlogits,corr=None):
    lq=jax.nn.log_softmax(qlogits); top_lp,top_ids=jax.lax.top_k(lq,K)
    def g(y):
        batch={"tokens":jnp.stack([jnp.zeros((),jnp.int32),y])[None],"mask":jnp.array([[False,True]]),"advantages":jnp.array([1.0]),
               "sampling_token_logprobs":jnp.stack([lq[y],0.])[None],
               "sampler_topk_ids":jnp.tile(top_ids,(1,2,1)),"sampler_topk_logprobs":jnp.tile(top_lp,(1,2,1))}
        return jax.grad(lambda W: mod.loss_fn_rl(h,lambda x:x@W,batch,corr)[0])(W)
    gs=jax.jit(jax.vmap(g))(jnp.arange(V))
    return float(jnp.abs(jnp.einsum('y,y...->...',jnp.exp(lq),gs)).max())
qoff=p_logits+0.5*jax.random.normal(jax.random.key(3),(V,))
for nm,m in [("orig",lo),("new",losses)]:
  for corr in [None, losses.ISCorrection(high=2.0,outside="clamp"), losses.ISCorrection()]:
    c = None if corr is None else m.ISCorrection(**corr._asdict())
    print(nm, corr, exp_grad(m,p_logits,c), exp_grad(m,qoff,c))
